verification.native_loop_driver:
use kujo::{
    compiler::Compiler,
    interpreter::{Environment, Interpreter, Value},
    lexer::tokenize,
    module::ModuleLoader,
    parser::Parser,
    vm::VM,
};
use std::sync::{Arc, Mutex};
fn check(environment: Environment, label: &str) -> bool {
    let globals = Arc::new(Mutex::new(environment));
    let source = r#"
        func delayed_override() {
            mut i := 0
            while i < 2048 {
                if i == 1800 { abs = 42 }
                i += 1
            }
        }
        delayed_override()
    "#;
    let source = std::env::args()
        .nth(2)
        .map(|path| std::fs::read_to_string(path).unwrap())
        .unwrap_or_else(|| source.to_string());
    let mut parser = Parser::new(tokenize(&source).unwrap());
    let chunk = Compiler::new().compile(&parser.parse()).unwrap();
    let mut vm = VM::new();
    vm.set_globals(Arc::clone(&globals));
    vm.set_jit_enabled(true);
    vm.execute(chunk).unwrap();
    let result = matches!(globals.lock().unwrap().get("abs"), Some(Value::Int(42)));
    println!("{label}: global_updated={result}");
    println!("COUNTERS {}", kujo::benchmarks::profiler::runtime::snapshot("success"));
    result
}
fn main() {
    kujo::benchmarks::profiler::runtime::start().unwrap();
    assert!(check(Interpreter::new().env, "explicit native preload"));
    let mut loader = ModuleLoader::new();
    loader.add_search_path(std::env::args().nth(1).unwrap());
    let module = loader.load_module("jit_loop_defaults").unwrap();
    let Value::Function(_, _, Some(environment)) = &module.exports["sentinel"] else {
        panic!("missing capture")
    };
    let environment = environment.lock().unwrap().clone();
    assert!(check(environment, "module native defaults"));
}

